window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"related-rates":{"id":"related-rates","prerequisites":["chain-rule","implicit-differentiation"],"next":["linear-approximation"],"related":[],"objectives":["把文字題寫成「幾個隨時間變化的量＋一條關係式」","對關係式兩邊對 $t$ 微分，用連鎖律帶出每個量的變化率","微分之後才代入「此刻」的數值，並檢查答案的正負與單位"],"concept":[{"heading":"① 綁在一起的量","body":["5 公尺的梯子靠牆，梯腳往外滑","梯腳離牆 $x$、頂端高度 $y$：都隨時間 $t$ 變","可是它們不是各變各的：","梯子、牆、地面圍成直角三角形，斜邊固定是 $5$","$x$ 一變，$y$ 就跟著變；所以變化率也綁在一起"],"tex":["x^2+y^2=25"]},{"heading":"② 整條式子對 $t$ 微分","body":["$x$、$y$ 都是 $t$ 的函數：$x=x(t)$、$y=y(t)$","兩邊是同一個函數，所以導數也相等：對 $t$ 微分","連鎖律：$\\dfrac{d}{dt}\\big(x^2\\big)=2x\\dfrac{dx}{dt}$","跟 2.13 隱函數微分一模一樣，只是這次對 $t$ 微分","此刻：$x=3$，$\\dfrac{dx}{dt}=1$；由 $3^2+y^2=25$ 得 $y=4$","頂端以每秒 $0.75$ 公尺下降"],"tex":["x(t)^2+y(t)^2=25\\quad\\text{（每個時刻都成立）}","2x\\frac{dx}{dt}+2y\\frac{dy}{dt}=0","2(3)(1)+2(4)\\frac{dy}{dt}=0","\\frac{dy}{dt}=-\\frac68=-\\frac34\\ \\text{m/s}"]},{"heading":"③ 五個步驟","body":["1. 畫圖、命名：哪些量在變？給它們名字","2. 寫已知、要求：已知 $\\frac{dx}{dt}$，求 $\\frac{dy}{dt}$","3. 找關係式：幾何、物理把量綁在一起","4. 對 $t$ 微分：每個變數都乘上它的變化率","5. 代入此刻的值，解出答案、看單位","常用的關係式：畢氏定理、面積體積公式、相似三角形"]},{"heading":"③ 例：氣球充氣","body":["球形氣球每秒充入 $100\\ \\text{cm}^3$；半徑 $r=5$ 時，$\\dfrac{dr}{dt}=$？","命名：體積 $V$、半徑 $r$","已知 $\\dfrac{dV}{dt}=100$；求 $r=5$ 時的 $\\dfrac{dr}{dt}$","關係式：","對 $t$ 微分（連鎖律）：","$4\\pi r^2$ 剛好是球的表面積：灌進去的體積，平均鋪在整個表面上","代入 $r=5$、$\\dfrac{dV}{dt}=100$：","半徑越大，表面積越大，同樣的充氣速率讓半徑長得越慢"],"tex":["V=\\frac43\\pi r^3","\\frac{dV}{dt}=4\\pi r^2\\frac{dr}{dt}","100=4\\pi(25)\\frac{dr}{dt}=100\\pi\\frac{dr}{dt}","\\frac{dr}{dt}=\\frac1\\pi\\approx0.32\\ \\text{cm/s}"]},{"heading":"④ 先微分，再代數字","body":["常見錯誤：一開始就把 $x=3$ 代進去","梯子題：先代 $x=3$，式子變成 $9+y^2=25$","錯在哪？$x=3$ 只在那一瞬間成立","順序：關係式要在每個時刻都成立，才能微分","• 微分之前：只能用「永遠成立」的關係","• 微分之後：才代入「此刻」的數值","但永遠不變的量可以先代：梯長 $5$、水槽的尺寸","判斷方法：問自己「這個數一秒後還是這個數嗎？」"],"tex":["\\frac{d}{dt}(9+y^2)=0\\ \\Rightarrow\\ 2y\\frac{dy}{dt}=0\\ \\Rightarrow\\ \\frac{dy}{dt}=0\\ ?"]},{"heading":"④ 例：圓錐水槽","body":["倒立圓錐水槽：頂半徑 $3$ m、高 $6$ m，每分鐘注水 $2\\ \\text{m}^3$。水深 $4$ m 時，水面上升多快？","水的形狀也是圓錐：水深 $h$、水面半徑 $r$","問題：有 $V$、$r$、$h$ 三個量，只知道 $\\frac{dV}{dt}$","相似三角形：$\\dfrac rh=\\dfrac36$，所以 $r=\\dfrac h2$"],"tex":["V=\\frac13\\pi r^2h"]},{"heading":"④ 圓錐水槽（續）","body":["代 $r=\\frac h2$，只剩 $h$：","對 $t$ 微分：","代 $h=4$、$\\dfrac{dV}{dt}=2$：","直覺：水越深，水面越寬，同樣的水量升得越慢","也可以問水面半徑：$\\frac{dr}{dt}=\\frac12\\frac{dh}{dt}=\\frac1{4\\pi}\\approx0.08$ m/min"],"tex":["V=\\frac13\\pi\\Big(\\frac h2\\Big)^2h=\\frac{\\pi}{12}h^3","\\frac{dV}{dt}=\\frac\\pi4h^2\\frac{dh}{dt}","2=\\frac\\pi4(16)\\frac{dh}{dt}=4\\pi\\frac{dh}{dt}","\\frac{dh}{dt}=\\frac{1}{2\\pi}\\approx0.16\\ \\text{m/min}"]},{"heading":"⑤ 正負號有意義","body":["$\\dfrac{dQ}{dt}>0$：增加；$\\dfrac{dQ}{dt}<0$：減少","已知的速率要配上正確的符號：","• 梯腳「遠離」牆：$\\frac{dx}{dt}=+1$","• 水槽「漏水」每分鐘 $2$：$\\frac{dV}{dt}=-2$","問「下降多快」：答 $\\frac{dy}{dt}=-\\frac34$，說成「以 $0.75$ m/s 下降」","梯腳 $x=4$ 時（$y=3$）："],"tex":["\\frac{dy}{dt}=-\\frac{x}{y}\\cdot\\frac{dx}{dt}=-\\frac43\\ \\text{m/s}"]},{"heading":"重點整理","body":["• 量綁在一條關係式上 ⇒ 變化率也綁在一起","• 整條式子對 $t$ 微分，每個變數乘上它的 $\\frac{d}{dt}$（連鎖律）","• 五步：畫圖命名 → 已知與所求 → 關係式 → 微分 → 代值","• 先微分、再代此刻的值；永遠不變的量可以先代","• 多一個量：用相似、畢氏把它消掉","• 正負號：正的在增加、負的在減少；答案寫單位","下一課：線性近似"]}],"workedExamples":[{"title":"梯子下滑","prompt":"5 公尺長的梯子靠牆，梯腳以每秒 1 公尺遠離牆。梯腳離牆 3 公尺時，頂端下降的速率是多少？","problemId":"dd-rr-001","steps":["命名：梯腳到牆 $x$、頂端高度 $y$，都是 $t$ 的函數。已知 $\\frac{dx}{dt}=1$，求 $\\frac{dy}{dt}$。","關係式（畢氏定理）：$x^2+y^2=25$。","對 $t$ 微分：$2x\\cdot\\frac{dx}{dt}+2y\\cdot\\frac{dy}{dt}=0$。","此刻 $x=3$，由 $x^2+y^2=25$ 得 $y=4$。代入：$2\\cdot 3\\cdot 1+2\\cdot 4\\cdot\\frac{dy}{dt}=0$，$\\frac{dy}{dt}=-\\frac{6}{8}=-\\frac{3}{4}$。","負號表示 $y$ 在變小。題目問下降的速率，答 $\\frac{3}{4}$ 公尺／秒。"],"answer":"每秒下降 $\\frac{3}{4}$ 公尺（$\\frac{dy}{dt}=-\\frac{3}{4}$）"},{"title":"氣球充氣","prompt":"球形氣球以每秒 100 立方公分充氣。半徑 5 公分時，半徑的變化率是多少？","problemId":"dd-rr-003","steps":["已知 $\\frac{dV}{dt}=100$，求 $\\frac{dr}{dt}$。關係式 $V=\\frac{4}{3}\\pi r^3$。","對 $t$ 微分：$\\frac{dV}{dt}=4\\pi r^2\\cdot\\frac{dr}{dt}$。","代 $r=5$：$100=4\\pi\\cdot 25\\cdot\\frac{dr}{dt}=100\\pi\\cdot\\frac{dr}{dt}$。","$\\frac{dr}{dt}=\\frac{1}{\\pi}\\approx 0.318$ 公分／秒。"],"answer":"$\\frac{1}{\\pi}$ 公分／秒","note":"灌氣速度固定，半徑卻越長越慢：$r$ 越大，$4\\pi r^2$ 越大，$\\frac{dr}{dt}$ 越小。"},{"title":"圓錐水槽：先消去多餘的量","prompt":"倒立圓錐水槽頂半徑 3 公尺、高 6 公尺，以每分鐘 2 立方公尺注水。水深 4 公尺時，水面上升的速率？","problemId":"db-rr-004","steps":["水的形狀是一個小圓錐，水面半徑 $r$、水深 $h$。$V=\\frac{1}{3}\\pi r^2h$，有 $r$、$h$ 兩個在變的量。","相似三角形：$\\frac{r}{h}=\\frac{3}{6}$，所以 $r=\\frac{h}{2}$。代進去消掉 $r$：$V=\\frac{1}{3}\\pi\\left(\\frac{h}{2}\\right)^2h=\\frac{\\pi h^3}{12}$。","對 $t$ 微分：$\\frac{dV}{dt}=\\frac{\\pi}{4}h^2\\cdot\\frac{dh}{dt}$。","代 $\\frac{dV}{dt}=2$、$h=4$：$2=\\frac{\\pi}{4}\\cdot 16\\cdot\\frac{dh}{dt}=4\\pi\\cdot\\frac{dh}{dt}$，$\\frac{dh}{dt}=\\frac{1}{2\\pi}\\approx 0.159$ 公尺／分。"],"answer":"$\\frac{1}{2\\pi}$ 公尺／分"}],"pitfalls":["先代數字再微分，把會變的量當成常數。","對 $t$ 微分時漏掉連鎖律，把 $\\frac{d}{dt}(r^3)$ 寫成 $3r^2$。","圓錐題沒先用相似三角形消去 $r$，留下兩個未知的變化率。","正負號對不上：「下降的速率」是正數，但 $\\frac{dy}{dt}$ 是負的。","此刻其他量的值沒有算，例如梯子題的 $y=4$ 要從關係式求。"],"voice":"525b2dbe","sections":[{"title":"綁在一起的量","beats":[{"show":["5 公尺的梯子靠牆，梯腳往外滑","梯腳離牆 $x$、頂端高度 $y$：都隨時間 $t$ 變"],"say":"一把 5 公尺的梯子靠在牆上，梯腳往外滑。梯腳離牆叫 x，頂端高度叫 y，兩個都隨時間在變。","board":[{"do":"write","line":"5 公尺的梯子靠牆，梯腳往外滑"},{"do":"write","line":"梯腳離牆 $x$、頂端高度 $y$：都隨時間 $t$ 變","on":"離牆"}],"t":[5030,17060]},{"show":["可是它們不是各變各的：","$x^2+y^2=25$"],"say":"但它們不是各變各的。梯長固定，由畢氏定理，x 平方加 y 平方永遠是 25。","board":[{"do":"write","line":"可是它們不是各變各的："},{"do":"write","line":"${{bx1:\\displaystyle x^2+y^2=25}}$","on":"梯長"},{"do":"box","term":"bx1","on":"平方#1"},{"do":"write","line":"　梯子、牆、地面圍成直角三角形，斜邊固定是 $5$","color":"violet","on":"平方#2"}],"t":[17060,26140]},{"show":["$x$ 一變，$y$ 就跟著變；所以變化率也綁在一起"],"say":"x 一變，y 就被迫跟著變。量綁在一起，變化率也綁在一起。","board":[{"do":"write","line":"$x$ 一變，$y$ 就跟著變；所以變化率也綁在一起"}],"t":[26140,34390]},{"show":["梯子長度固定：x 變大，y 就變小"],"say":"看圖。梯腳往外移，","board":[{"do":"plot","nb":{"spec":{"id":"lad","window":[-0.6,6,-0.6,5.6],"equal":true,"lines":[{"from":[0,0],"to":[0,5.6],"color":"ink"},{"from":[-0.6,0],"to":[6,0],"color":"ink"},{"from":["x",0],"to":[0,"sqrt(25-x^2)"],"color":"blue"}],"points":[{"x":"x","y":0,"label":"梯腳","color":"red"},{"x":0,"y":"sqrt(25-x^2)","label":"頂端","color":"blue"}],"params":{"x":{"min":0.6,"max":4.8,"value":3,"label":"梯腳離牆 x"}},"readout":"頂端高度 y = {sqrt(25-x^2)}","height":300}}},{"do":"write","line":"頂端高度 y = 4","on":"梯腳"},{"do":"write","line":"梯子長度固定：x 變大，y 就變小","color":"violet","on":"外移"}],"t":[34390,38320]},{"show":["綁在一起的量"],"say":"頂端就往下掉：梯腳從 3 走到 4 點 2，頂端從 4 掉到大約 2 點 7。","board":[{"do":"plot","nb":{"spec":{"id":"lad","window":[-0.6,6,-0.6,5.6],"equal":true,"lines":[{"from":[0,0],"to":[0,5.6],"color":"ink"},{"from":[-0.6,0],"to":[6,0],"color":"ink"},{"from":["x",0],"to":[0,"sqrt(25-x^2)"],"color":"blue"}],"points":[{"x":"x","y":0,"label":"梯腳","color":"red"},{"x":0,"y":"sqrt(25-x^2)","label":"頂端","color":"blue"}],"params":{"x":{"min":0.6,"max":4.8,"value":3,"label":"梯腳離牆 x"}},"readout":"頂端高度 y = {sqrt(25-x^2)}","height":300},"vals":{"x":4.2}}},{"do":"write","line":"頂端高度 y = 2.713","on":"頂端#2"}],"t":[38320,47220]}]},{"title":"先猜猜看","beats":[{"show":["梯腳以每秒 $1$ 公尺往外滑。頂端下降的速率呢？"],"say":"先猜猜看。梯腳每秒移 1 公尺，頂端掉下來的速率也是每秒 1 公尺嗎？","t":[47220,60260]}],"predict":{"ask":"梯腳以每秒 $1$ 公尺往外滑。頂端==下降==的速率呢？","options":[{"label":"也是每秒 $1$ 公尺","why":"梯子長度不變，不代表兩端走得一樣快：它們綁的是 $x^2+y^2$，不是 $x+y$"},{"label":"不一定，要看梯子此刻的位置","correct":true},{"label":"永遠比 $1$ 慢","why":"梯子快躺平時，頂端掉得非常快（下面會看到）"}]}},{"title":"整條式子對 $t$ 微分","beats":[{"show":["$x$、$y$ 都是 $t$ 的函數：$x=x(t)$、$y=y(t)$","$x(t)^2+y(t)^2=25\\quad\\text{（每個時刻都成立）}$"],"say":"關鍵想法：x 和 y 都是時間的函數，這條式子每一個時刻都成立。","board":[{"do":"write","line":"$x$、$y$ 都是 $t$ 的函數：$x=x(t)$、$y=y(t)$"},{"do":"write","line":"$\\displaystyle x(t)^2+y(t)^2=25\\quad\\text{（每個時刻都成立）}$","on":"函數"}],"t":[60260,67380]},{"show":["兩邊是同一個函數，所以導數也相等：對 $t$ 微分"],"say":"兩邊每個時刻都相等，導數也就相等。所以整條式子對 t 微分。","board":[{"do":"write","line":"兩邊是同一個函數，所以導數也相等：對 $t$ 微分"}],"t":[67380,74920]},{"show":["連鎖律：$\\dfrac{d}{dt}\\big(x^2\\big)=2x\\dfrac{dx}{dt}$"],"say":"微分 x 平方要用連鎖律：2x，再乘上 d x d t。","board":[{"do":"write","line":"連鎖律：$\\dfrac{d}{dt}\\big(x^2\\big)=2x\\dfrac{dx}{dt}$"},{"do":"write","line":"　跟 2.13 隱函數微分一模一樣，只是這次對 $t$ 微分","color":"violet","on":"再乘"}],"t":[74920,80960]},{"show":["$2x\\frac{dx}{dt}+2y\\frac{dy}{dt}=0$"],"say":"y 平方也一樣，25 的導數是 0。這條式子把 d x d t 和 d y d t 綁在一起。","board":[{"do":"write","line":"${{bx2:\\displaystyle 2x\\frac{dx}{dt}+2y\\frac{dy}{dt}=0}}$"},{"do":"box","term":"bx2","on":"綁在"}],"t":[80960,91460]},{"show":["此刻：$x=3$，$\\dfrac{dx}{dt}=1$；由 $3^2+y^2=25$ 得 $y=4$"],"say":"代入此刻：x 等於 3，梯腳速率 1。y 用原本的關係式算，是 4。","board":[{"do":"write","line":"此刻：$x=3$，$\\dfrac{dx}{dt}=1$；由 $3^2+y^2=25$ 得 $y=4$"}],"t":[91460,101710]},{"show":["$2(3)(1)+2(4)\\frac{dy}{dt}=0$","$\\frac{dy}{dt}=-\\frac68=-\\frac34\\ \\text{m/s}$"],"say":"代進去：6 加 8 倍 d y d t 等於 0，d y d t 是負 4 分之 3，公尺每秒。","board":[{"do":"write","line":"$\\displaystyle 2(3)(1)+2(4)\\frac{dy}{dt}=0$"},{"do":"write","line":"${{bx3:\\displaystyle \\frac{dy}{dt}=-\\frac68=-\\frac34\\ \\text{m/s}}}$","color":"red","on":"等於"},{"do":"box","term":"bx3","color":"red","on":"是負"}],"t":[101710,111710]},{"show":["頂端以每秒 $0.75$ 公尺下降"],"say":"負號表示 y 在變小：頂端以每秒 0.75 公尺往下掉。","board":[{"do":"write","line":"頂端以每秒 $0.75$ 公尺下降"}],"t":[111710,122490]}]},{"title":"五個步驟","beats":[{"show":["1. 畫圖、命名：哪些量在變？給它們名字","2. 寫已知、要求：已知 $\\frac{dx}{dt}$，求 $\\frac{dy}{dt}$"],"say":"整理成五步。第一，畫圖，替會變的量命名。第二，寫下已知和要求的變化率。第三，找關係式。","board":[{"do":"write","line":"1. 畫圖、命名：哪些量在變？給它們名字"},{"do":"write","line":"2. 寫已知、要求：已知 $\\frac{dx}{dt}$，求 $\\frac{dy}{dt}$","on":"變的"},{"do":"write","line":"3. 找關係式：幾何、物理把量綁在一起","on":"要求"}],"t":[122490,136890]},{"show":["4. 對 $t$ 微分：每個變數都乘上它的變化率","5. 代入此刻的值，解出答案、看單位"],"say":"第四，整條式子對 t 微分。第五，最後才代入此刻的數值，檢查單位。","board":[{"do":"write","line":"4. 對 $t$ 微分：每個變數都乘上它的變化率"},{"do":"write","line":"5. 代入此刻的值，解出答案、看單位","on":"微分"},{"do":"write","line":"　常用的關係式：畢氏定理、面積體積公式、相似三角形","color":"violet","on":"此刻"}],"t":[136890,146100]}],"proof":true,"order":{"ask":"把相關變率題做完的順序","steps":[{"label":"畫圖，替會變的量命名"},{"label":"寫下已知的變化率和要求的變化率","why":"先要有上一步：畫圖，替會變的量命名"},{"label":"找出量之間的關係式","why":"先要有上一步：寫下已知的變化率和要求的變化率"},{"label":"關係式兩邊對 $t$ 微分","why":"先要有上一步：找出量之間的關係式"},{"label":"代入此刻的數值，解出並寫單位","why":"先要有上一步：關係式兩邊對 $t$ 微分"}]}},{"title":"例：氣球充氣","beats":[{"show":["球形氣球每秒充入 $100\\ \\text{cm}^3$；半徑 $r=5$ 時，$\\dfrac{dr}{dt}=$？"],"say":"用五步做一題。氣球每秒灌進 100 立方公分，半徑 5 公分那一刻，半徑長得多快？","board":[{"do":"write","line":"球形氣球每秒充入 $100\\ \\text{cm}^3$；半徑 $r=5$ 時，$\\dfrac{dr}{dt}=$？"}],"t":[156840,170140]},{"show":["命名：體積 $V$、半徑 $r$","已知 $\\dfrac{dV}{dt}=100$；求 $r=5$ 時的 $\\dfrac{dr}{dt}$"],"say":"會變的是體積 V 和半徑 r。綁住它們的是球的體積公式：3 分之 4 派 r 立方。","board":[{"do":"write","line":"命名：體積 $V$、半徑 $r$"},{"do":"write","line":"已知 $\\dfrac{dV}{dt}=100$；求 $r=5$ 時的 $\\dfrac{dr}{dt}$","on":"半徑"},{"do":"write","line":"關係式：","on":"球的"},{"do":"write","line":"$\\displaystyle V=\\frac43\\pi r^3$","on":"立方"}],"t":[170140,180980]},{"show":["對 $t$ 微分（連鎖律）：","$\\frac{dV}{dt}=4\\pi r^2\\frac{dr}{dt}$"],"say":"對 t 微分：得 4 派 r 平方，乘 d r d t。","board":[{"do":"write","line":"對 $t$ 微分（連鎖律）："},{"do":"write","line":"$\\displaystyle \\frac{dV}{dt}=4\\pi r^2\\frac{dr}{dt}$","on":"平方"},{"do":"write","line":"　$4\\pi r^2$ 剛好是球的表面積：灌進去的體積，平均鋪在整個表面上","color":"violet","on":"t。"}],"t":[180980,190350]},{"show":["代入 $r=5$、$\\dfrac{dV}{dt}=100$：","$100=4\\pi(25)\\frac{dr}{dt}=100\\pi\\frac{dr}{dt}$"],"say":"代入：100 等於 100 派乘 d r d t，所以 d r d t 是派分之一，大約每秒 0.32 公分。","board":[{"do":"write","line":"代入 $r=5$、$\\dfrac{dV}{dt}=100$："},{"do":"write","line":"$\\displaystyle 100=4\\pi(25)\\frac{dr}{dt}=100\\pi\\frac{dr}{dt}$","on":"00#2"},{"do":"write","line":"${{bx4:\\displaystyle \\frac{dr}{dt}=\\frac1\\pi\\approx0.32\\ \\text{cm/s}}}$","color":"red","on":"所以"},{"do":"box","term":"bx4","color":"red","on":"是派"},{"do":"write","line":"　半徑越大，表面積越大，同樣的充氣速率讓半徑長得越慢","color":"violet","on":"每秒"}],"t":[190350,202450]}]},{"title":"試一題","beats":[{"show":["石頭丟進池塘，圓形波紋的半徑每秒增加 $2$ cm。半徑 $5$ cm 時，面積增加的速率是？"],"say":"換你試一題。","t":[202450,213740]}],"check":0},{"title":"先微分，再代數字","beats":[{"show":["常見錯誤：一開始就把 $x=3$ 代進去"],"say":"最常見的錯誤，是一開始就把此刻的數值代進去。","board":[{"do":"write","line":"常見錯誤：一開始就把 $x=3$ 代進去","color":"red"}],"t":[213740,221100]},{"show":["梯子題：先代 $x=3$，式子變成 $9+y^2=25$","$\\frac{d}{dt}(9+y^2)=0\\ \\Rightarrow\\ 2y\\frac{dy}{dt}=0\\ \\Rightarrow\\ \\frac{dy}{dt}=0\\ ?$"],"say":"像梯子題，先把 x 換成 3，再微分，9 的導數是 0，結果頂端完全不動？顯然不對。","board":[{"do":"write","line":"梯子題：先代 $x=3$，式子變成 $9+y^2=25$"},{"do":"write","line":"$\\displaystyle \\frac{d}{dt}(9+y^2)=0\\ \\Rightarrow\\ 2y\\frac{dy}{dt}=0\\ \\Rightarrow\\ \\frac{dy}{dt}=0\\ ?$","on":"的導"}],"t":[221100,231100]},{"show":["錯在哪？$x=3$ 只在那一瞬間成立"],"say":"x 等於 3 只在那一瞬間成立。把它當常數，就弄丟了它的變化率。","board":[{"do":"write","line":"錯在哪？$x=3$ 只在那一瞬間成立","color":"gold"}],"t":[231100,243500]},{"show":["順序：關係式要在每個時刻都成立，才能微分","• 微分之前：只能用「永遠成立」的關係"],"say":"所以微分之前，只能放永遠成立的關係；此刻的數值，微分完才代。","board":[{"do":"write","line":"順序：關係式要在每個時刻都成立，才能微分"},{"do":"write","line":"• 微分之前：只能用「永遠成立」的關係","on":"永遠"},{"do":"write","line":"• 微分之後：才代入「此刻」的數值","on":"的數"}],"t":[243500,251050]},{"show":["但永遠不變的量可以先代：梯長 $5$、水槽的尺寸"],"say":"本來就不變的量，像梯長、水槽尺寸，可以先放進去。","board":[{"do":"write","line":"但永遠不變的量可以先代：梯長 $5$、水槽的尺寸"},{"do":"write","line":"　判斷方法：問自己「這個數一秒後還是這個數嗎？」","color":"violet","on":"水槽"}],"t":[251050,258150]}]},{"title":"例：圓錐水槽","beats":[{"show":["倒立圓錐水槽：頂半徑 $3$ m、高 $6$ m，每分鐘注水 $2\\ \\text{m}^3$。水深 $4$ m 時，水面上升多快？"],"say":"倒立的圓錐水槽，頂半徑 3 公尺，高 6 公尺，每分鐘注水 2 立方公尺。水深 4 公尺時，水面升得多快？","board":[{"do":"write","line":"倒立圓錐水槽：頂半徑 $3$ m、高 $6$ m，每分鐘注水 $2\\ \\text{m}^3$。水深 $4$ m 時，水面上升多快？"}],"t":[258150,271620]},{"show":["水的形狀也是圓錐：水深 $h$、水面半徑 $r$","$V=\\frac13\\pi r^2h$"],"say":"水也是倒立圓錐，水深 h、水面半徑 r，體積是 3 分之 1 派 r 平方 h。","board":[{"do":"write","line":"水的形狀也是圓錐：水深 $h$、水面半徑 $r$"},{"do":"write","line":"$\\displaystyle V=\\frac13\\pi r^2h$","on":"體積"}],"t":[271620,280020]},{"show":["問題：有 $V$、$r$、$h$ 三個量，只知道 $\\frac{dV}{dt}$"],"say":"三個會變的量，只知道一個變化率，要先消去多餘的那個。","board":[{"do":"write","line":"問題：有 $V$、$r$、$h$ 三個量，只知道 $\\frac{dV}{dt}$"}],"t":[280020,286880]},{"show":["圖"],"say":"看側面圖：水的小三角形，跟水槽的大三角形相似。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 620 300\" width=\"620\"><polygon points=\"190,40 430,40 310,280\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"3\"/><polygon points=\"230,120 390,120 310,280\" fill=\"var(--blue)\" fill-opacity=\"0.2\" stroke=\"var(--blue)\" stroke-width=\"3\"/><line x1=\"310\" y1=\"40\" x2=\"430\" y2=\"40\" stroke=\"var(--ink)\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><line x1=\"310\" y1=\"120\" x2=\"390\" y2=\"120\" stroke=\"var(--blue)\" stroke-width=\"2\" stroke-dasharray=\"7 6\"/><line x1=\"310\" y1=\"40\" x2=\"310\" y2=\"280\" stroke=\"var(--muted)\" stroke-width=\"2\" stroke-dasharray=\"4 5\"/><text x=\"370\" y=\"30\" text-anchor=\"middle\" style=\"font-family:KaTeX_Main,serif;font-size:22px;fill:var(--ink)\">3</text><text x=\"350\" y=\"112\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:22px;fill:var(--blue)\">r</text><line x1=\"470\" y1=\"40\" x2=\"470\" y2=\"280\" stroke=\"var(--ink)\" stroke-width=\"2\"/><line x1=\"462\" y1=\"40\" x2=\"478\" y2=\"40\" stroke=\"var(--ink)\" stroke-width=\"2\"/><line x1=\"462\" y1=\"280\" x2=\"478\" y2=\"280\" stroke=\"var(--ink)\" stroke-width=\"2\"/><text x=\"486\" y=\"168\" style=\"font-family:KaTeX_Main,serif;font-size:22px;fill:var(--ink)\">6</text><line x1=\"150\" y1=\"120\" x2=\"150\" y2=\"280\" stroke=\"var(--blue)\" stroke-width=\"2\"/><line x1=\"142\" y1=\"120\" x2=\"158\" y2=\"120\" stroke=\"var(--blue)\" stroke-width=\"2\"/><line x1=\"142\" y1=\"280\" x2=\"158\" y2=\"280\" stroke=\"var(--blue)\" stroke-width=\"2\"/><text x=\"128\" y=\"208\" text-anchor=\"end\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:22px;fill:var(--blue)\">h</text></svg>"}],"t":[286880,292960]},{"show":["相似三角形：$\\dfrac rh=\\dfrac36$，所以 $r=\\dfrac h2$"],"say":"半徑比高等於 3 比 6，水面半徑永遠是水深的一半。這是永遠成立的，可以先代。","board":[{"do":"write","line":"相似三角形：$\\dfrac rh=\\dfrac36$，所以 $r=\\dfrac h2$","color":"gold"}],"t":[292960,304740]}]},{"title":"圓錐水槽（續）","beats":[{"show":["代 $r=\\frac h2$，只剩 $h$：","$V=\\frac13\\pi\\Big(\\frac h2\\Big)^2h=\\frac{\\pi}{12}h^3$"],"say":"把 r 換成 2 分之 h，體積是 12 分之派乘 h 立方。","board":[{"do":"write","line":"代 $r=\\frac h2$，只剩 $h$："},{"do":"write","line":"$\\displaystyle V=\\frac13\\pi\\Big(\\frac h2\\Big)^2h=\\frac{\\pi}{12}h^3$","on":"積是"}],"t":[304740,312490]},{"show":["對 $t$ 微分：","$\\frac{dV}{dt}=\\frac\\pi4h^2\\frac{dh}{dt}$"],"say":"對 t 微分：4 分之派 h 平方，乘 d h d t。","board":[{"do":"write","line":"對 $t$ 微分："},{"do":"write","line":"$\\displaystyle \\frac{dV}{dt}=\\frac\\pi4h^2\\frac{dh}{dt}$","on":"平方"}],"t":[312490,319780]},{"show":["代 $h=4$、$\\dfrac{dV}{dt}=2$：","$2=\\frac\\pi4(16)\\frac{dh}{dt}=4\\pi\\frac{dh}{dt}$"],"say":"現在才代入 h 等於 4、d V d t 等於 2：2 等於 4 派乘 d h d t。","board":[{"do":"write","line":"代 $h=4$、$\\dfrac{dV}{dt}=2$："},{"do":"write","line":"$\\displaystyle 2=\\frac\\pi4(16)\\frac{dh}{dt}=4\\pi\\frac{dh}{dt}$","on":"等於#3"}],"t":[319780,329680]},{"show":["$\\frac{dh}{dt}=\\frac{1}{2\\pi}\\approx0.16\\ \\text{m/min}$"],"say":"所以水面每分鐘上升 2 派分之一，大約 0.16 公尺。","board":[{"do":"write","line":"${{bx5:\\displaystyle \\frac{dh}{dt}=\\frac{1}{2\\pi}\\approx0.16\\ \\text{m/min}}}$","color":"red"},{"do":"box","term":"bx5","color":"red","on":"之一"}],"t":[329680,335800]},{"show":["直覺：水越深，水面越寬，同樣的水量升得越慢"],"say":"直覺檢查：水越深，水面越寬，水面升得越慢。","board":[{"do":"write","line":"直覺：水越深，水面越寬，同樣的水量升得越慢"},{"do":"write","line":"　也可以問水面半徑：$\\frac{dr}{dt}=\\frac12\\frac{dh}{dt}=\\frac1{4\\pi}\\approx0.08$ m/min","color":"violet","on":"面越"}],"t":[335800,342520]}]},{"title":"正負號有意義","beats":[{"show":["$\\dfrac{dQ}{dt}>0$：增加；$\\dfrac{dQ}{dt}<0$：減少"],"say":"最後談正負號。變化率是正的，量在增加；是負的，量在減少。","board":[{"do":"write","line":"$\\dfrac{dQ}{dt}>0$：增加；$\\dfrac{dQ}{dt}<0$：減少","color":"gold"}],"t":[342520,353810]},{"show":["已知的速率要配上正確的符號：","• 梯腳「遠離」牆：$\\frac{dx}{dt}=+1$"],"say":"題目給的速率要先定符號：梯腳遠離牆是正 1；水槽漏水，體積變小，要寫負 2。","board":[{"do":"write","line":"已知的速率要配上正確的符號："},{"do":"write","line":"• 梯腳「遠離」牆：$\\frac{dx}{dt}=+1$","on":"梯腳"},{"do":"write","line":"• 水槽「漏水」每分鐘 $2$：$\\frac{dV}{dt}=-2$","on":"體積"}],"t":[353810,362680]},{"show":["問「下降多快」：答 $\\frac{dy}{dt}=-\\frac34$，說成「以 $0.75$ m/s 下降」"],"say":"回答也一樣：d y d t 是負 4 分之 3，就說以每秒 0.75 公尺下降。","board":[{"do":"write","line":"問「下降多快」：答 $\\frac{dy}{dt}=-\\frac34$，說成「以 $0.75$ m/s 下降」"}],"t":[362680,373220]},{"show":["梯腳 $x=4$ 時（$y=3$）：","$\\frac{dy}{dt}=-\\frac{x}{y}\\cdot\\frac{dx}{dt}=-\\frac43\\ \\text{m/s}$"],"say":"梯腳離牆 4 公尺時，y 是 3，d y d t 是負 3 分之 4：頂端掉得比梯腳移得快。","board":[{"do":"write","line":"梯腳 $x=4$ 時（$y=3$）："},{"do":"write","line":"$\\displaystyle \\frac{dy}{dt}=-\\frac{x}{y}\\cdot\\frac{dx}{dt}=-\\frac43\\ \\text{m/s}$","on":"是負"}],"t":[373220,384620]},{"show":["圖"],"say":"x 越接近 5，y 越接近 0，頂端掉得越來越快。","board":[{"do":"plot","nb":{"spec":{"id":"lad2","window":[-0.6,6,-0.6,5.6],"equal":true,"lines":[{"from":[0,0],"to":[0,5.6],"color":"ink"},{"from":[-0.6,0],"to":[6,0],"color":"ink"},{"from":["x",0],"to":[0,"sqrt(25-x^2)"],"color":"blue"}],"points":[{"x":"x","y":0,"color":"red"},{"x":0,"y":"sqrt(25-x^2)","color":"blue"}],"params":{"x":{"min":0.6,"max":4.8,"value":4,"label":"梯腳離牆 x"}},"readout":"頂端高度 y = {sqrt(25-x^2)}","height":230}}},{"do":"write","line":"頂端高度 y = 3","on":"越接#2"},{"do":"plot","nb":{"spec":{"id":"lad2","window":[-0.6,6,-0.6,5.6],"equal":true,"lines":[{"from":[0,0],"to":[0,5.6],"color":"ink"},{"from":[-0.6,0],"to":[6,0],"color":"ink"},{"from":["x",0],"to":[0,"sqrt(25-x^2)"],"color":"blue"}],"points":[{"x":"x","y":0,"color":"red"},{"x":0,"y":"sqrt(25-x^2)","color":"blue"}],"params":{"x":{"min":0.6,"max":4.8,"value":4,"label":"梯腳離牆 x"}},"readout":"頂端高度 y = {sqrt(25-x^2)}","height":230},"vals":{"x":4.8}},"on":"頂端"},{"do":"write","line":"頂端高度 y = 1.4","on":"掉得"}],"t":[384620,390840]}]},{"title":"試一題","beats":[{"show":["梯腳仍以 $1$ m/s 往外滑。梯腳離牆 $4.8$ m 時（$y=1.4$），$\\frac{dy}{dt}$ 約是？"],"say":"試一題。梯腳離牆 4.8 公尺的時候呢？","t":[390840,412260]}],"check":1},{"title":"重點整理","beats":[{"show":["• 量綁在一條關係式上 ⇒ 變化率也綁在一起","• 整條式子對 $t$ 微分，每個變數乘上它的 $\\frac{d}{dt}$（連鎖律）"],"say":"整理一下：量綁在一起，變化率也綁在一起；整條式子對 t 微分，先微分、再代此刻的值；多的量用相似消掉；最後看正負號、寫單位。下一課，用切線估計函數值。","board":[{"do":"write","line":"• 量綁在一條關係式上 ⇒ 變化率也綁在一起"},{"do":"write","line":"• 整條式子對 $t$ 微分，每個變數乘上它的 $\\frac{d}{dt}$（連鎖律）","on":"變化"},{"do":"write","line":"• 五步：畫圖命名 → 已知與所求 → 關係式 → 微分 → 代值","on":"條式"},{"do":"write","line":"• 先微分、再代此刻的值；永遠不變的量可以先代","on":"微分#2"},{"do":"write","line":"• 多一個量：用相似、畢氏把它消掉","on":"多的"},{"do":"write","line":"• 正負號：正的在增加、負的在減少；答案寫單位","on":"看正"},{"do":"write","line":"下一課：線性近似","on":"用切"}],"t":[412260,432692]}]}],"checks":[{"ask":"石頭丟進池塘，圓形波紋的半徑每秒增加 $2$ cm。半徑 $5$ cm 時，面積增加的速率是？","options":[{"label":"$20\\pi\\ \\text{cm}^2/\\text{s}$","correct":true},{"label":"$4\\pi\\ \\text{cm}^2/\\text{s}$","why":"漏了 $r$：$\\frac{d}{dt}(\\pi r^2)=2\\pi r\\frac{dr}{dt}$，不是 $2\\pi\\frac{dr}{dt}$"},{"label":"$10\\pi\\ \\text{cm}^2/\\text{s}$","why":"漏了連鎖律的 $\\frac{dr}{dt}=2$：$2\\pi r$ 只是 $\\frac{dA}{dr}$"},{"label":"$25\\pi\\ \\text{cm}^2/\\text{s}$","why":"那是此刻的面積 $\\pi r^2$，不是面積的變化率"}]},{"ask":"梯腳仍以 $1$ m/s 往外滑。梯腳離牆 $4.8$ m 時（$y=1.4$），$\\frac{dy}{dt}$ 約是？","options":[{"label":"$-3.43$ m/s","correct":true},{"label":"$3.43$ m/s","why":"漏了負號：$y$ 在變小"},{"label":"$-0.29$ m/s","why":"把 $\\frac xy$ 寫反成 $\\frac yx$ 了"},{"label":"$-1$ m/s","why":"兩端速率不一樣；比值是 $\\frac xy$"}]}],"practice":[{"id":"dd-rr-013","core":true},{"id":"dd-rr-002","core":true},{"id":"lec-03-q4a","core":true},{"id":"dd-rr-012","core":true},{"id":"db-rr-003","core":true},{"id":"dd-rr-003","core":true},{"id":"dd-rr-005","core":true},{"id":"dd-rr-004","core":true},{"id":"dd-rr-009","core":true},{"id":"db-rr-007"},{"id":"dd-rr-007"},{"id":"dd-rr-008"},{"id":"db-rr-008"},{"id":"dd-rr-011"},{"id":"dx-rr-003","challenge":true,"note":"挑戰：兩船一個往南、一個往東，先寫出 2 小時後兩船的位置。"},{"id":"dd-rr-010","challenge":true,"note":"挑戰：並聯電阻 $\\frac{1}{R}=\\frac{1}{R_1}+\\frac{1}{R_2}$，三個量同時在變。"}]},"linear-approximation":{"id":"linear-approximation","prerequisites":["secant-to-tangent","derivative-definition","derivative-power-rules","derivative-trig"],"next":["differentials-error"],"related":["concavity","taylor-polynomial","taylor-error"],"objectives":["寫出 $f$ 在 $x=a$ 的線性近似 $L(x)=f(a)+f'(a)(x-a)$，並用它估計 $\\sqrt{4.1}$ 這類的值","選一個「好算又夠近」的 $a$","從曲線的凹向判斷估計值偏高還是偏低","說明為什麼誤差比 $h$ 小得多"],"concept":[{"heading":"① 放大就變直線","body":["$\\sqrt{4.1}$ 是多少？手邊沒有計算機","畫 $y=\\sqrt x$ 和它在 $x=4$ 的切線","可微的曲線，放大夠多看起來就是直線：它的切線","2.2 從割線走到切線，講的就是這件事"]},{"heading":"② 公式","body":["$f$ 在 $x=a$ 的切線，就是線性近似：","$x$ 靠近 $a$ 時：$f(x)\\approx L(x)$","寫成 $x=a+h$ 的樣子：","白話：新的值 ≈ 舊的值 ＋ 斜率 × 走的距離","例：$\\sqrt{4.1}$。$f(x)=\\sqrt x$，$a=4$，$h=0.1$","$f(4)=2$；$f'(x)=\\dfrac1{2\\sqrt x}$，$f'(4)=\\dfrac14$","真正的值：$\\sqrt{4.1}=2.02484\\ldots$，差 $0.00015$"],"tex":["L(x)=f(a)+f'(a)(x-a)","f(a+h)\\approx f(a)+f'(a)\\,h","\\sqrt{4.1}\\approx2+\\frac14(0.1)=2.025"]},{"heading":"③ 怎麼選 $a$","body":["兩個條件：","• $f(a)$、$f'(a)$ 好算（例如完全平方、完全立方、特殊角）","• $a$ 夠靠近要估的 $x$（$h$ 小）","估 $\\sqrt{4.1}$ 若取 $a=1$：$1+\\frac12(3.1)=2.55$，離真值差很多","例：$\\sqrt[3]{8.06}$。$f(x)=x^{1/3}$，取 $a=8$，$h=0.06$","$f(8)=2$；$f'(x)=\\dfrac13x^{-2/3}$","真值 $2.004988\\ldots$，差約 $0.000012$"],"tex":["f'(8)=\\frac13\\cdot\\frac14=\\frac1{12}","\\sqrt[3]{8.06}\\approx2+\\frac{0.06}{12}=2.005"]},{"heading":"③ 角度要換成弧度","body":["估 $\\sin31^\\circ$：取 $a=30^\\circ$，$f=\\sin$，$f'=\\cos$","但 $(\\sin x)'=\\cos x$ 只在弧度下成立","2.6 推導 $\\frac{d}{dx}\\sin x$ 時用了 $\\lim\\frac{\\sin x}{x}=1$，那是弧度","$a=\\dfrac\\pi6$，$h=1^\\circ=\\dfrac{\\pi}{180}\\approx0.017453$","真值 $0.51504\\ldots$","錯誤示範：$h$ 用 $1$（度）→ $\\frac12+\\frac{\\sqrt3}2\\approx1.366$"],"tex":["\\sin31^\\circ\\approx\\sin\\frac\\pi6+\\cos\\frac\\pi6\\cdot\\frac\\pi{180}","=\\frac12+\\frac{\\sqrt3}2\\cdot\\frac{\\pi}{180}\\approx0.51511"]},{"heading":"④ 偏高還是偏低","body":["看曲線往哪邊彎（凹向）：","• 往下彎（$f''<0$）：切線在曲線上面 → 估計偏高","• 往上彎（$f''>0$）：切線在曲線下面 → 估計偏低","二階導數與凹向在 3A 學過","$\\sqrt x$：$f''(x)=-\\frac14x^{-3/2}<0$，往下彎","$\\sin x$ 在 $\\frac\\pi6$：$f''=-\\sin\\frac\\pi6<0$ → $0.51511$ 也偏高"],"tex":["2.025>\\sqrt{4.1}\\quad\\text{（偏高）}"]},{"heading":"⑤ 誤差比 $h$ 小得多","body":["誤差 $E(h)=f(a+h)-\\big[f(a)+f'(a)h\\big]$；$\\sqrt x$、$a=4$：","$h$ 變成 $\\frac1{10}$，誤差大約變成 $\\frac1{100}$","為什麼？ 誤差除以 $h$：","$h\\to0$：割線斜率 $\\to f'(a)$（導數的定義）","更精確：$E(h)\\approx\\frac12f''(a)h^2$；證明留到泰勒多項式","切線是唯一有這個性質的直線"],"tex":["\\begin{aligned}h=1:&\\quad |E|\\approx0.014\\\\h=0.1:&\\quad |E|\\approx0.00015\\\\h=0.01:&\\quad |E|\\approx0.0000016\\end{aligned}","\\frac{E(h)}{h}=\\frac{f(a+h)-f(a)}{h}-f'(a)","\\lim_{h\\to0}\\frac{E(h)}{h}=f'(a)-f'(a)=0"]},{"heading":"重點整理","body":["• 線性近似：$L(x)=f(a)+f'(a)(x-a)$，就是切線","• $f(a+h)\\approx f(a)+f'(a)h$：舊值 ＋ 斜率 × 步長","• 選 $a$：$f(a)$、$f'(a)$ 好算，又靠近要估的點","• 三角函數：$h$ 一定用弧度","• 往下彎 → 偏高；往上彎 → 偏低","• 誤差 $\\frac{E(h)}{h}\\to0$：比 $h$ 小得多","下一課：微分與誤差估計"]}],"workedExamples":[{"title":"估計 $\\sqrt{4.1}$","prompt":"用 $f(x)=\\sqrt{x}$ 在 $x=4$ 的線性近似估計 $\\sqrt{4.1}$。","problemId":"lec-05-m3","steps":["$a=4$，$h=0.1$。$f(4)=\\sqrt{4}=2$。","$f'(x)=\\frac{1}{2\\sqrt{x}}$，$f'(4)=\\frac{1}{2\\cdot 2}=\\frac{1}{4}$。","$\\sqrt{4.1}\\approx 2+\\frac{1}{4}(0.1)=2.025$。","$\\sqrt{x}$ 凹向下，這個估計偏高。真值約 $2.024846$。"],"answer":"$2.025$"},{"title":"立方根","prompt":"用線性近似估計 $\\sqrt[3]{8.06}$。","problemId":"dd-lin-001","steps":["選 $a=8$，因為 $\\sqrt[3]{8}=2$。$h=0.06$。","$f(x)=x^{1/3}$，$f'(x)=\\frac{1}{3}x^{-2/3}$。$f'(8)=\\frac{1}{3}\\cdot 8^{-2/3}=\\frac{1}{3}\\cdot\\frac{1}{4}=\\frac{1}{12}$。","$\\sqrt[3]{8.06}\\approx 2+\\frac{1}{12}(0.06)=2+0.005=2.005$。"],"answer":"$2.005$"},{"title":"角度要換成弧度","prompt":"用線性近似估計 $\\sin 31^\\circ$。","problemId":"db-lin-004","steps":["選 $a=30^\\circ=\\frac{\\pi}{6}$，$\\sin\\frac{\\pi}{6}=\\frac{1}{2}$。","$h$ 是 $1^\\circ$，換成弧度：$h=\\frac{\\pi}{180}$。$(\\sin x)'=\\cos x$ 這條公式只在弧度下成立。","$f'\\left(\\frac{\\pi}{6}\\right)=\\cos\\frac{\\pi}{6}=\\frac{\\sqrt{3}}{2}$。","$\\sin 31^\\circ\\approx\\frac{1}{2}+\\frac{\\sqrt{3}}{2}\\cdot\\frac{\\pi}{180}=\\frac{1}{2}+\\frac{\\sqrt{3}\\pi}{360}\\approx 0.51511$。真值約 $0.51504$。"],"answer":"$\\frac{1}{2}+\\frac{\\sqrt{3}\\pi}{360}\\approx 0.51511$"}],"pitfalls":["把 $f(a)$ 漏掉，只寫 $f'(a)h$。","把 $f'(a)$ 寫成 $f'(x)$，得到的不是一條直線。","三角函數用角度當 $h$。","$a$ 選離目標太遠，或選一個 $f(a)$ 自己都算不出來的 $a$。"],"voice":"e460c3e9","sections":[{"title":"放大就變直線","beats":[{"show":["$\\sqrt{4.1}$ 是多少？手邊沒有計算機"],"say":"不用計算機，根號 4.1 大概是多少？這一課的想法很簡單：用切線代替曲線。","board":[{"do":"write","line":"$\\sqrt{4.1}$ 是多少？手邊沒有計算機"}],"t":[2980,12180]},{"show":["畫 $y=\\sqrt x$ 和它在 $x=4$ 的切線"],"say":"先畫根號 x，和它在 x 等於 4 的切線。","board":[{"do":"write","line":"畫 $y=\\sqrt x$ 和它在 $x=4$ 的切線"}],"t":[12180,17040]},{"show":["遠看：曲線和切線分得很開"],"say":"遠遠看，曲線和切線分得很開：離 4 越遠，差越多。","board":[{"do":"plot","nb":{"spec":{"id":"wide","window":[0,9,0,3.6],"fn":[{"expr":"sqrt(x)","color":"blue","label":"y = √x"},{"expr":"2+(x-4)/4","color":"red","dash":true,"label":"切線"}],"points":[{"x":4,"y":2,"color":"ink"}],"height":230}}},{"do":"write","line":"遠看：曲線和切線分得很開","color":"violet","on":"越遠"}],"t":[17040,24190]},{"show":["放大到 [3.8, 4.2]：幾乎疊在一起"],"say":"可是把 4 附近放大，只看 3.8 到 4.2，兩條線幾乎疊在一起，分不出來。","board":[{"do":"plot","nb":{"spec":{"id":"zoom","window":[3.8,4.2,1.95,2.05],"fn":[{"expr":"sqrt(x)","color":"blue"},{"expr":"2+(x-4)/4","color":"red","dash":true}],"points":[{"x":4,"y":2,"color":"ink"}],"height":230}}},{"do":"write","line":"放大到 [3.8, 4.2]：幾乎疊在一起","color":"violet","on":"兩條"}],"t":[24190,32630]},{"show":["可微的曲線，放大夠多看起來就是直線：它的切線"],"say":"這是可微函數的特色：放大夠多，曲線看起來就是一條直線，也就是它的切線。所以在 4 附近，用切線算，就差不多是曲線的值。","board":[{"do":"write","line":"可微的曲線，放大夠多看起來就是直線：它的切線","color":"gold"},{"do":"write","line":"　2.2 從割線走到切線，講的就是這件事","color":"violet","on":"是它"}],"t":[32630,46960]}]},{"title":"先猜猜看","beats":[{"show":["用 $x=4$ 的切線估計 $\\sqrt{4.1}$，跟真正的值比？"],"say":"先猜猜看：用切線估計出來的根號 4.1，會比真的值大還是小？","t":[46960,58530]}],"predict":{"ask":"用 $x=4$ 的切線估計 $\\sqrt{4.1}$，跟真正的值比？","options":[{"label":"稍微偏高","correct":true},{"label":"稍微偏低","why":"方向反了：$\\sqrt x$ 是往下彎的，切線在上面"},{"label":"剛好相等","why":"只有在 $x=4$ 剛好相等；離開 $4$ 就有一點誤差"}]}},{"title":"公式","beats":[{"show":["$f$ 在 $x=a$ 的切線，就是線性近似：","$L(x)=f(a)+f'(a)(x-a)$"],"say":"f 在 x 等於 a 的切線，叫做線性近似，記作 L of x：f of a，加上 f prime a，乘上 x 減 a。","board":[{"do":"write","line":"$f$ 在 $x=a$ 的切線，就是線性近似："},{"do":"write","line":"${{bx1:\\displaystyle L(x)=f(a)+f'(a)(x-a)}}$","on":"記作"},{"do":"box","term":"bx1","on":"pr"}],"t":[58530,71130]},{"show":["$x$ 靠近 $a$ 時：$f(x)\\approx L(x)$"],"say":"x 靠近 a 的時候，f of x 大約等於 L of x。","board":[{"do":"write","line":"$x$ 靠近 $a$ 時：$f(x)\\approx L(x)$"}],"t":[71130,78940]},{"show":["寫成 $x=a+h$ 的樣子：","$f(a+h)\\approx f(a)+f'(a)\\,h$"],"say":"把 x 寫成 a 加 h，h 是往右走的一小步，就是這個樣子：f of a 加 h，大約是 f of a，加上斜率乘 h。","board":[{"do":"write","line":"寫成 $x=a+h$ 的樣子："},{"do":"write","line":"${{bx2:\\displaystyle f(a+h)\\approx f(a)+f'(a)\\,h}}$","on":"是往"},{"do":"box","term":"bx2","on":"of#1"},{"do":"write","line":"　白話：新的值 ≈ 舊的值 ＋ 斜率 × 走的距離","color":"violet","on":"of#2"}],"t":[78940,92240]},{"show":["例：$\\sqrt{4.1}$。$f(x)=\\sqrt x$，$a=4$，$h=0.1$"],"say":"回到根號 4.1。f 是根號 x，a 取 4，h 是 0.1。","board":[{"do":"write","line":"例：$\\sqrt{4.1}$。$f(x)=\\sqrt x$，$a=4$，$h=0.1$"}],"t":[92240,99330]},{"show":["$f(4)=2$；$f'(x)=\\dfrac1{2\\sqrt x}$，$f'(4)=\\dfrac14$"],"say":"f of 4 是 2。根號 x 的導數是 2 根號 x 分之一，代 4 得到 4 分之 1。","board":[{"do":"write","line":"$f(4)=2$；$f'(x)=\\dfrac1{2\\sqrt x}$，$f'(4)=\\dfrac14$"}],"t":[99330,108930]},{"show":["$\\sqrt{4.1}\\approx2+\\frac14(0.1)=2.025$"],"say":"所以根號 4.1，大約是 2 加 4 分之 1 乘 0.1，等於 2.025。","board":[{"do":"write","line":"${{bx3:\\displaystyle \\sqrt{4.1}\\approx2+\\frac14(0.1)=2.025}}$","color":"red"},{"do":"box","term":"bx3","color":"red","on":"分之"}],"t":[108930,117130]},{"show":["真正的值：$\\sqrt{4.1}=2.02484\\ldots$，差 $0.00015$"],"say":"真正的值是 2.02484 多一點，只差了大約一萬分之一點五。只用了一次除法，就準到小數第三位。","board":[{"do":"write","line":"真正的值：$\\sqrt{4.1}=2.02484\\ldots$，差 $0.00015$"}],"t":[117130,130190]}]},{"title":"怎麼選 $a$","beats":[{"show":["兩個條件：","• $f(a)$、$f'(a)$ 好算（例如完全平方、完全立方、特殊角）"],"say":"a 要怎麼選？兩個條件。第一，f of a 和 f prime a 要好算，像完全平方數、完全立方數、特殊角。","board":[{"do":"write","line":"兩個條件："},{"do":"write","line":"• $f(a)$、$f'(a)$ 好算（例如完全平方、完全立方、特殊角）","on":"ri"}],"t":[130190,141590]},{"show":["• $a$ 夠靠近要估的 $x$（$h$ 小）"],"say":"第二，a 要夠靠近要估的那個數，h 越小越準。","board":[{"do":"write","line":"• $a$ 夠靠近要估的 $x$（$h$ 小）"},{"do":"write","line":"　估 $\\sqrt{4.1}$ 若取 $a=1$：$1+\\frac12(3.1)=2.55$，離真值差很多","color":"violet","on":"的那"}],"t":[141590,146940]},{"show":["例：$\\sqrt[3]{8.06}$。$f(x)=x^{1/3}$，取 $a=8$，$h=0.06$"],"say":"例子：8.06 的立方根。f 是 x 的 3 分之 1 次方。8 是完全立方，又很靠近 8.06，所以取 a 等於 8，h 是 0.06。","board":[{"do":"write","line":"例：$\\sqrt[3]{8.06}$。$f(x)=x^{1/3}$，取 $a=8$，$h=0.06$"}],"t":[146940,163270]},{"show":["$f(8)=2$；$f'(x)=\\dfrac13x^{-2/3}$","$f'(8)=\\frac13\\cdot\\frac14=\\frac1{12}$"],"say":"f of 8 是 2。導數是 3 分之 1 乘 x 的負 3 分之 2 次方；8 的 3 分之 2 次方是 4，所以斜率是 12 分之 1。","board":[{"do":"write","line":"$f(8)=2$；$f'(x)=\\dfrac13x^{-2/3}$"},{"do":"write","line":"$\\displaystyle f'(8)=\\frac13\\cdot\\frac14=\\frac1{12}$","on":"次方#1"}],"t":[163270,177670]},{"show":["$\\sqrt[3]{8.06}\\approx2+\\frac{0.06}{12}=2.005$"],"say":"立方根 8.06，大約是 2 加 12 分之 0.06，等於 2.005。","board":[{"do":"write","line":"${{bx4:\\displaystyle \\sqrt[3]{8.06}\\approx2+\\frac{0.06}{12}=2.005}}$","color":"red"},{"do":"box","term":"bx4","color":"red","on":"12"},{"do":"write","line":"　真值 $2.004988\\ldots$，差約 $0.000012$","color":"violet","on":"06#2"}],"t":[177670,185470]}],"check":0},{"title":"角度要換成弧度","beats":[{"show":["估 $\\sin31^\\circ$：取 $a=30^\\circ$，$f=\\sin$，$f'=\\cos$"],"say":"再一個例子：正弦 31 度。取 a 等於 30 度，正弦和餘弦都是特殊角，很好算。","board":[{"do":"write","line":"估 $\\sin31^\\circ$：取 $a=30^\\circ$，$f=\\sin$，$f'=\\cos$"}],"t":[195440,204880]},{"show":["但 $(\\sin x)'=\\cos x$ 只在弧度下成立"],"say":"但要小心：正弦的導數是餘弦，這個公式只在弧度下成立。所以 a 和 h 都要換成弧度。","board":[{"do":"write","line":"但 $(\\sin x)'=\\cos x$ 只在弧度下成立","color":"red"},{"do":"write","line":"　2.6 推導 $\\frac{d}{dx}\\sin x$ 時用了 $\\lim\\frac{\\sin x}{x}=1$，那是弧度","color":"violet","on":"度下"}],"t":[204880,214670]},{"show":["$a=\\dfrac\\pi6$，$h=1^\\circ=\\dfrac{\\pi}{180}\\approx0.017453$"],"say":"30 度是 6 分之派；走的一步是 1 度，換成弧度是 180 分之派，大約 0.017453。","board":[{"do":"write","line":"$a=\\dfrac\\pi6$，$h=1^\\circ=\\dfrac{\\pi}{180}\\approx0.017453$"}],"t":[214670,227310]},{"show":["$\\sin31^\\circ\\approx\\sin\\frac\\pi6+\\cos\\frac\\pi6\\cdot\\frac\\pi{180}$","$=\\frac12+\\frac{\\sqrt3}2\\cdot\\frac{\\pi}{180}\\approx0.51511$"],"say":"代進公式：正弦 6 分之派是 2 分之 1，加上餘弦 6 分之派，2 分之根號 3，乘 180 分之派，大約是 0.51511。","board":[{"do":"write","line":"$\\displaystyle \\sin31^\\circ\\approx\\sin\\frac\\pi6+\\cos\\frac\\pi6\\cdot\\frac\\pi{180}$"},{"do":"write","line":"${{bx5:\\displaystyle =\\frac12+\\frac{\\sqrt3}2\\cdot\\frac{\\pi}{180}\\approx0.51511}}$","color":"red","on":"分之#2"},{"do":"box","term":"bx5","color":"red","on":"分之#4"},{"do":"write","line":"　真值 $0.51504\\ldots$","color":"violet","on":"分之#5"}],"t":[227310,240510]},{"show":["錯誤示範：$h$ 用 $1$（度）→ $\\frac12+\\frac{\\sqrt3}2\\approx1.366$"],"say":"如果忘了換，h 直接用 1，會得到 1.366。正弦不可能大於 1，一看就知道錯了。","board":[{"do":"write","line":"錯誤示範：$h$ 用 $1$（度）→ $\\frac12+\\frac{\\sqrt3}2\\approx1.366$","color":"red"}],"t":[240510,254720]}]},{"title":"偏高還是偏低","beats":[{"show":["看曲線往哪邊彎（凹向）：","• 往下彎（$f''<0$）：切線在曲線上面 → 估計偏高"],"say":"估計值偏高還是偏低，看曲線往哪邊彎。往下彎，也就是二階導數小於零，切線在曲線上面，估計偏高。往上彎，二階導數大於零，切線在曲線下面，估計偏低。","board":[{"do":"write","line":"看曲線往哪邊彎（凹向）："},{"do":"write","line":"• 往下彎（$f''<0$）：切線在曲線上面 → 估計偏高","on":"往下"},{"do":"write","line":"• 往上彎（$f''>0$）：切線在曲線下面 → 估計偏低","on":"在曲#1"},{"do":"write","line":"　二階導數與凹向在 3A 學過","color":"violet","on":"數大"}],"t":[254720,274140]},{"show":["$\\sqrt x$：$f''(x)=-\\frac14x^{-3/2}<0$，往下彎","$2.025>\\sqrt{4.1}\\quad\\text{（偏高）}$"],"say":"根號 x 的二階導數是負 4 分之 1 乘 x 的負 2 分之 3 次方，是負的，往下彎。所以 2.025 偏高，跟剛剛真值比的結果一致。","board":[{"do":"write","line":"$\\sqrt x$：$f''(x)=-\\frac14x^{-3/2}<0$，往下彎"},{"do":"write","line":"${{bx6:\\displaystyle 2.025>\\sqrt{4.1}\\quad\\text{（偏高）}}}$","on":"的負"},{"do":"box","term":"bx6","on":"02"}],"t":[274140,289040]},{"show":["往下彎：切線兩邊都在曲線上面"],"say":"圖上，根號 x 往下彎，切線不管往左往右，都在曲線上面。所以不管 h 是正是負，估計都偏高。","board":[{"do":"plot","nb":{"spec":{"id":"conc","window":[2,7,1.3,2.8],"fn":[{"expr":"sqrt(x)","color":"blue","label":"y = √x"},{"expr":"2+(x-4)/4","color":"red","dash":true,"label":"切線"}],"points":[{"x":4,"y":2,"color":"ink"}],"height":250}}},{"do":"write","line":"往下彎：切線兩邊都在曲線上面","color":"violet","on":"曲線"}],"t":[289040,300080]},{"show":["$\\sin x$ 在 $\\frac\\pi6$：$f''=-\\sin\\frac\\pi6<0$ → $0.51511$ 也偏高"],"say":"正弦 31 度那題也一樣：正弦的二階導數是負正弦，在 6 分之派是負的，所以 0.51511 也偏高。","board":[{"do":"write","line":"$\\sin x$ 在 $\\frac\\pi6$：$f''=-\\sin\\frac\\pi6<0$ → $0.51511$ 也偏高"}],"t":[300080,311380]}]},{"title":"試一題","beats":[{"show":["用 $x=0$ 的線性近似：$e^{0.1}\\approx1+0.1=1.1$。這個估計是？"],"say":"換你判斷。用 0 的切線估計 e 的 0.1 次方，得到 1.1。偏高還是偏低？","t":[311380,321040]}],"check":1},{"title":"誤差比 $h$ 小得多","beats":[{"show":["誤差 $E(h)=f(a+h)-\\big[f(a)+f'(a)h\\big]$；$\\sqrt x$、$a=4$："],"say":"最後看誤差。誤差 E of h 定義成真的值減掉線性近似。用根號 x、a 等於 4 來算幾個。","board":[{"do":"write","line":"誤差 $E(h)=f(a+h)-\\big[f(a)+f'(a)h\\big]$；$\\sqrt x$、$a=4$："}],"t":[321040,331180]},{"show":["$\\begin{aligned}h=1:&\\quad |E|\\approx0.014\\\\h=0.1:&\\quad |E|\\approx0.00015\\\\h=0.01:&\\quad |E|\\approx0.0000016\\end{aligned}$"],"say":"h 是 1，誤差約 0.014；h 是 0.1，誤差約 0.00015；h 是 0.01，誤差約 0.0000016。","board":[{"do":"write","line":"$\\displaystyle {\\begin{aligned}h=1:&\\quad |E|\\approx0.014\\\\h=0.1:&\\quad |E|\\approx0.00015\\\\h=0.01:&\\quad |E|\\approx0.0000016\\end{aligned}}$"}],"t":[331180,343380]},{"show":["$h$ 變成 $\\frac1{10}$，誤差大約變成 $\\frac1{100}$"],"say":"發現了嗎？h 縮小成 10 分之 1，誤差大約縮小成 100 分之 1。誤差跟 h 平方差不多大，比 h 小得多。","board":[{"do":"write","line":"$h$ 變成 $\\frac1{10}$，誤差大約變成 $\\frac1{100}$","color":"gold"}],"t":[343380,357230]},{"show":["為什麼？ 誤差除以 $h$：","$\\frac{E(h)}{h}=\\frac{f(a+h)-f(a)}{h}-f'(a)$"],"say":"為什麼？把誤差除以 h。式子變成：割線斜率，減掉切線斜率。","board":[{"do":"write","line":"為什麼？ 誤差除以 $h$："},{"do":"write","line":"$\\displaystyle \\frac{E(h)}{h}=\\frac{f(a+h)-f(a)}{h}-f'(a)$","on":"變成"}],"t":[357230,367920]},{"show":["$h\\to0$：割線斜率 $\\to f'(a)$（導數的定義）","$\\lim_{h\\to0}\\frac{E(h)}{h}=f'(a)-f'(a)=0$"],"say":"h 趨近 0，割線斜率趨近 f prime a，這正是導數的定義。所以誤差除以 h 趨近 0：誤差跟 h 比起來，小到可以忽略。","board":[{"do":"write","line":"$h\\to0$：割線斜率 $\\to f'(a)$（導數的定義）"},{"do":"write","line":"${{bx7:\\displaystyle \\lim_{h\\to0}\\frac{E(h)}{h}=f'(a)-f'(a)=0}}$","color":"red","on":"pr"},{"do":"box","term":"bx7","color":"red","on":"所以"},{"do":"write","line":"　更精確：$E(h)\\approx\\frac12f''(a)h^2$；證明留到泰勒多項式","color":"violet","on":"差跟"}],"t":[367920,381120]},{"show":["切線是唯一有這個性質的直線"],"say":"而且，換成任何其他斜率的直線，誤差除以 h 會趨近一個不是 0 的數。所以切線是最好的直線近似。","board":[{"do":"write","line":"切線是唯一有這個性質的直線"}],"t":[381120,402480]}]},{"title":"重點整理","beats":[{"show":["• 線性近似：$L(x)=f(a)+f'(a)(x-a)$，就是切線","• $f(a+h)\\approx f(a)+f'(a)h$：舊值 ＋ 斜率 × 步長"],"say":"整理一下：線性近似就是切線；選 a 要好算又靠近；三角函數要用弧度；往下彎的曲線估計偏高，往上彎的偏低；誤差比 h 小得多，這就是切線好用的原因。","board":[{"do":"write","line":"• 線性近似：$L(x)=f(a)+f'(a)(x-a)$，就是切線"},{"do":"write","line":"• $f(a+h)\\approx f(a)+f'(a)h$：舊值 ＋ 斜率 × 步長","on":"要好"},{"do":"write","line":"• 選 $a$：$f(a)$、$f'(a)$ 好算，又靠近要估的點","on":"三角"},{"do":"write","line":"• 三角函數：$h$ 一定用弧度","on":"彎的#1"},{"do":"write","line":"• 往下彎 → 偏高；往上彎 → 偏低","on":"的偏"},{"do":"write","line":"• 誤差 $\\frac{E(h)}{h}\\to0$：比 $h$ 小得多","on":"這就"}],"t":[402480,417640]},{"show":["下一課：微分與誤差估計"],"say":"下一課，我們把 f prime 乘 h 這一項取個名字，叫做微分，用它來估計量測誤差。","board":[{"do":"write","line":"下一課：微分與誤差估計"}],"t":[417640,428199]}]}],"checks":[{"ask":"估計 $\\sqrt{26}$，最好的 $a$ 是？","options":[{"label":"$a=25$，得 $5.1$","correct":true},{"label":"$a=26$","why":"$\\sqrt{26}$ 正是我們不會算的，$f(a)$ 要好算"},{"label":"$a=36$，得 $5\\frac16$","why":"$36$ 好算但離 $26$ 太遠：$6+\\frac1{12}(-10)\\approx5.17$，誤差大"},{"label":"$a=16$，得 $5.25$","why":"太遠了：$4+\\frac18(10)=5.25$"}]},{"ask":"用 $x=0$ 的線性近似：$e^{0.1}\\approx1+0.1=1.1$。這個估計是？","options":[{"label":"偏低","correct":true},{"label":"偏高","why":"方向反了：$e^x$ 往上彎，切線在曲線下面"},{"label":"剛好相等","why":"只有 $x=0$ 時相等"},{"label":"不能判斷","why":"看二階導數的正負就能判斷"}]}],"practice":[{"id":"lec-05-m3","core":true},{"id":"db-tan-004","core":true},{"id":"db-lin-001","core":true},{"id":"dd-lin-002","core":true},{"id":"lec-05-q4a"},{"id":"dd-lin-003","core":true},{"id":"tb-lin-002","core":true},{"id":"tb-lin-003"},{"id":"db-lin-003"},{"id":"db-lin-004","core":true},{"id":"cg-3d-001","core":true},{"id":"tb-lin-004"},{"id":"cg-3d-002"},{"id":"db-lin-008","challenge":true,"note":"挑戰：$\\arctan 1.1$，要記得 $\\arctan 1=\\frac{\\pi}{4}$ 與 $(\\arctan x)'$。"}]},"differentials-error":{"id":"differentials-error","prerequisites":["linear-approximation"],"next":["rolle-theorem"],"related":[],"objectives":["分清楚 $dy$（沿切線的變化）與 $\\Delta y$（實際的變化），會算 $dy=f'(x)\\,dx$","用 $dy$ 估計量測誤差傳到計算結果的大小","算相對誤差與百分比誤差，看出 $y=x^n$ 的相對誤差會放大 $n$ 倍"],"concept":[{"heading":"① $\\Delta y$ 與 $dy$","body":["$x$ 走一小步 $dx$（也寫 $\\Delta x$），$y=f(x)$ 跟著變：","• 真的走：$\\Delta y=f(x+dx)-f(x)$","• 沿切線走：$dy=f'(x)\\,dx$","$dy$ 叫做 $y$ 的微分；$dx$ 很小時 $\\Delta y\\approx dy$","$\\frac{dy}{dx}$ 原本是一個整體的符號；定義了 $dy=f'(x)dx$ 之後，它剛好也是 $dy$ 除以 $dx$"]},{"heading":"① 例：正方形","body":["$y=x^2$（正方形面積），$x=3$，$dx=0.1$","$dy=2x\\,dx=2(3)(0.1)=0.6$","$\\Delta y=3.1^2-9=0.61$","差了 $(dx)^2=0.01$：很小的平方，更小"],"tex":["\\Delta y=\\underbrace{2x\\,dx}_{dy}+(dx)^2"]},{"heading":"② 量測誤差會傳下去","body":["量 $x$ 有誤差 $dx$ → 用 $x$ 算出的 $y=f(x)$ 也有誤差","$f'(x)$ 就是「放大倍率」：$x$ 差一點，$y$ 差 $f'(x)$ 倍那麼多","例：量得球的半徑 $r=10$ cm，誤差最多 $0.05$ cm。體積的最大誤差？","代 $r=10$、$|dr|\\le0.05$：","真正的 $\\Delta V$：半徑多 $0.05$ 時約 $63.1$，少 $0.05$ 時約 $-62.5$，都跟 $62.8$ 很接近","看起來很多？體積本身 $\\frac43\\pi(1000)\\approx4189$ cm³"],"tex":["\\text{誤差}\\ \\Delta y\\approx dy=f'(x)\\,dx","V=\\frac43\\pi r^3,\\qquad dV=4\\pi r^2\\,dr","|dV|\\le4\\pi(100)(0.05)=20\\pi\\approx62.8\\ \\text{cm}^3"]},{"heading":"② 試一題：正立方體","body":["$V=s^3$，$dV=3s^2\\,ds$：","真的 $\\Delta V=5.02^3-125=1.506008$，只差 $0.006$","放大倍率 $V'(5)=75$：邊長差 $1$ 份，體積差 $75$ 份"],"tex":["dV=3(5)^2(0.02)=1.5\\ \\text{cm}^3"]},{"heading":"③ 相對誤差","body":["相對誤差＝誤差 ÷ 本身：$\\dfrac{dy}{y}$；乘 $100\\%$ 是百分比誤差","球：","半徑的相對誤差：$\\dfrac{0.05}{10}=0.5\\%$","體積的相對誤差剛好是 3 倍","為什麼是 3 倍？ $y=x^n$：","$y=x^n$ 的相對誤差＝$n$ 倍的 $x$ 的相對誤差","前面的常數（像 $\\frac43\\pi$）約掉了，不影響相對誤差","正立方體：$\\dfrac{dV}{V}=3\\cdot\\dfrac{0.02}5=1.2\\%$"],"tex":["\\frac{dV}{V}=\\frac{20\\pi}{\\frac43\\pi(1000)}=\\frac{60}{4000}=1.5\\%","\\frac{dy}{y}=\\frac{nx^{n-1}\\,dx}{x^n}=n\\,\\frac{dx}{x}"]},{"heading":"③ 反過來：要量多準","body":["用 $A=\\pi r^2$ 算圓面積，要 $\\left|\\dfrac{dA}{A}\\right|\\le1\\%$","$A$ 是 $r$ 的 2 次方：","例：半徑約 $20$ cm，就要量到 $\\pm0.1$ cm 以內"],"tex":["\\frac{dA}{A}=2\\,\\frac{dr}{r}","2\\left|\\frac{dr}r\\right|\\le1\\%\\ \\Rightarrow\\ \\left|\\frac{dr}r\\right|\\le0.5\\%"]},{"heading":"重點整理","body":["• $dy=f'(x)\\,dx$：沿切線的變化；$\\Delta y$：真正的變化","• $dx$ 小時 $\\Delta y\\approx dy$（差的是 $(dx)^2$ 那種更小的量）","• 量測誤差：$|\\Delta y|\\approx|f'(x)|\\,|dx|$，$f'$ 是放大倍率","• 相對誤差 $\\frac{dy}y$；百分比誤差再乘 $100\\%$","• $y=x^n$：相對誤差放大 $n$ 倍；反過來要求就除以 $n$","下一課：Rolle 定理"]}],"workedExamples":[{"title":"球的體積誤差","prompt":"量得球的半徑 10 公分，誤差最多 0.05 公分。用微分估計體積的最大誤差。","problemId":"dd-lin-004","steps":["$V=\\frac{4}{3}\\pi r^3$，$V'(r)=4\\pi r^2$。","$dV=4\\pi r^2\\,dr=4\\pi\\cdot 10^2\\cdot 0.05=20\\pi\\approx 62.8$ 立方公分。","相對誤差：$\\frac{dV}{V}=3\\cdot\\frac{dr}{r}=3\\cdot\\frac{0.05}{10}=0.015$，也就是 $1.5\\%$。半徑只差 $0.5\\%$，體積差了三倍。"],"answer":"$20\\pi\\approx 62.8$ 立方公分（相對誤差約 $1.5\\%$）","note":"實際的 $\\Delta V=\\frac{4}{3}\\pi(10.05^3-10^3)\\approx 63.15$，跟 $dV\\approx 62.83$ 很接近，但不相等。"},{"title":"正立方體","prompt":"正立方體的邊長量得 5 公分，誤差 0.02 公分。用微分估計體積的誤差。","problemId":"dd-lin-005","steps":["$V=s^3$，$dV=3s^2\\,ds$。","$dV=3\\cdot 5^2\\cdot 0.02=3\\cdot 25\\cdot 0.02=1.5$ 立方公分。"],"answer":"$1.5$ 立方公分"},{"title":"反過來：要量多準","prompt":"用 $A=\\pi r^2$ 算圓面積，要讓面積的相對誤差不超過 $1\\%$。半徑的相對誤差最多可以是多少？","steps":["$dA=2\\pi r\\,dr$，除以 $A=\\pi r^2$：$\\frac{dA}{A}=2\\cdot\\frac{dr}{r}$。","要 $\\left|\\frac{dA}{A}\\right|\\le 1\\%$，就要 $2\\left|\\frac{dr}{r}\\right|\\le 1\\%$。","所以 $\\left|\\frac{dr}{r}\\right|\\le 0.5\\%$。"],"answer":"$0.5\\%$"}],"pitfalls":["把 $dy$ 當成精確的 $\\Delta y$。$dy$ 是沿切線的估計。","算相對誤差時用 $dy$ 除以 $dx$，應該是除以 $y$。","以為相對誤差在計算中保持不變；$y=x^n$ 會放大成 $n$ 倍。","$f'(x)$ 代錯點：要代量到的值（例如 $r=10$），不是誤差 $0.05$。"],"voice":"09d13290","sections":[{"title":"$\\Delta y$ 與 $dy$","beats":[{"show":["$x$ 走一小步 $dx$（也寫 $\\Delta x$），$y=f(x)$ 跟著變："],"say":"上一課的線性近似，換一個寫法。x 走一小步，叫 d x，也就是 得爾塔 x。y 等於 f of x 也跟著變。","board":[{"do":"write","line":"$x$ 走一小步 $dx$（也寫 $\\Delta x$），$y=f(x)$ 跟著變："}],"t":[2980,16160]},{"show":["• 真的走：$\\Delta y=f(x+dx)-f(x)$","• 沿切線走：$dy=f'(x)\\,dx$"],"say":"有兩種變化。真的沿著曲線走，變化叫 得爾塔 y，是 f of x 加 d x，減 f of x。沿著切線走，變化叫 d y，是斜率乘上 d x。","board":[{"do":"write","line":"• 真的走：$\\Delta y=f(x+dx)-f(x)$"},{"do":"write","line":"• 沿切線走：$dy=f'(x)\\,dx$","on":"of#2"}],"t":[16160,30960]},{"show":["$dy$ 叫做 $y$ 的微分；$dx$ 很小時 $\\Delta y\\approx dy$"],"say":"d y 叫做 y 的微分。d x 很小的時候，得爾塔 y 大約等於 d y。這就是上一課的線性近似，換個名字而已。","board":[{"do":"write","line":"$dy$ 叫做 $y$ 的微分；$dx$ 很小時 $\\Delta y\\approx dy$","color":"gold"},{"do":"write","line":"　$\\frac{dy}{dx}$ 原本是一個整體的符號；定義了 $dy=f'(x)dx$ 之後，它剛好也是 $dy$ 除以 $dx$","color":"violet","on":"大約"}],"t":[30960,43510]},{"show":["藍：Δy（沿曲線）；紅點：dy（沿切線）"],"say":"圖上，從 x 等於 1 出發。藍色線段的高是 得爾塔 y，紅點是沿切線走到的高度。d x 大的時候，兩個差很多。","board":[{"do":"plot","nb":{"spec":{"id":"dd","window":[0.6,3.4,-0.5,9],"fn":[{"expr":"x^2","color":"blue","label":"y = x²"},{"expr":"1+2*(x-1)","color":"red","dash":true,"label":"切線"}],"points":[{"x":1,"y":1,"color":"ink"},{"x":"1+d","y":"(1+d)^2","color":"blue"},{"x":"1+d","y":"1+2*d","color":"red"}],"lines":[{"from":[1,1],"to":["1+d",1],"color":"pencil","dash":true},{"from":["1+d",1],"to":["1+d","(1+d)^2"],"color":"blue"}],"params":{"d":{"min":0.1,"max":2,"value":1.6,"label":"dx"}},"readout":"Δy = {(1+d)^2-1}，dy = {2*d}","height":280}}},{"do":"write","line":"Δy = 5.76，dy = 3.2","on":"段的"},{"do":"write","line":"藍：Δy（沿曲線）；紅點：dy（沿切線）","color":"violet","on":"的高#2"}],"t":[43510,55880]},{"show":["$\\Delta y$ 與 $dy$"],"say":"d x 越縮越小，藍點和紅點越靠越近，得爾塔 y 和 d y 幾乎一樣。","board":[{"do":"plot","nb":{"spec":{"id":"dd","window":[0.6,3.4,-0.5,9],"fn":[{"expr":"x^2","color":"blue","label":"y = x²"},{"expr":"1+2*(x-1)","color":"red","dash":true,"label":"切線"}],"points":[{"x":1,"y":1,"color":"ink"},{"x":"1+d","y":"(1+d)^2","color":"blue"},{"x":"1+d","y":"1+2*d","color":"red"}],"lines":[{"from":[1,1],"to":["1+d",1],"color":"pencil","dash":true},{"from":["1+d",1],"to":["1+d","(1+d)^2"],"color":"blue"}],"params":{"d":{"min":0.1,"max":2,"value":1.6,"label":"dx"}},"readout":"Δy = {(1+d)^2-1}，dy = {2*d}","height":280},"vals":{"d":0.1}}},{"do":"write","line":"Δy = 0.21，dy = 0.2","on":"得爾"}],"t":[55880,64180]}]},{"title":"例：正方形","beats":[{"show":["$y=x^2$（正方形面積），$x=3$，$dx=0.1$"],"say":"用正方形的面積來看。邊長 x 是 3，增加 0.1。","board":[{"do":"write","line":"$y=x^2$（正方形面積），$x=3$，$dx=0.1$"}],"t":[64180,70780]},{"show":["$dy=2x\\,dx=2(3)(0.1)=0.6$"],"say":"微分 d y 是 2x 乘 d x，2 乘 3 乘 0.1，等於 0.6。","board":[{"do":"write","line":"$dy=2x\\,dx=2(3)(0.1)=0.6$"}],"t":[70780,78580]},{"show":["$\\Delta y=3.1^2-9=0.61$"],"say":"真正的變化 得爾塔 y，是 3.1 的平方減 9，等於 0.61。","board":[{"do":"write","line":"$\\Delta y=3.1^2-9=0.61$"}],"t":[78580,85580]},{"show":["差了 $(dx)^2=0.01$：很小的平方，更小"],"say":"兩個只差 0.01，剛好是 d x 的平方。d x 本身小，它的平方更小，所以可以丟掉。","board":[{"do":"write","line":"差了 $(dx)^2=0.01$：很小的平方，更小","color":"gold"}],"t":[85580,96120]},{"show":["圖"],"say":"畫出來就很清楚：邊長多了 d x，多出兩條紅色長條，各是 x 乘 d x，合起來就是 d y。角落那一小塊灰色，是 d x 平方，d y 沒算到它。","board":[{"do":"plot","svg":"<svg viewBox=\"0 0 620 330\" width=\"620\"><rect x=\"160\" y=\"60\" width=\"240\" height=\"240\" fill=\"var(--blue)\" fill-opacity=\"0.1\" stroke=\"var(--ink)\" stroke-width=\"3\"/><rect x=\"400\" y=\"60\" width=\"40\" height=\"240\" fill=\"var(--red)\" fill-opacity=\"0.2\" stroke=\"var(--red)\" stroke-width=\"2\"/><rect x=\"160\" y=\"20\" width=\"240\" height=\"40\" fill=\"var(--red)\" fill-opacity=\"0.2\" stroke=\"var(--red)\" stroke-width=\"2\"/><rect x=\"400\" y=\"20\" width=\"40\" height=\"40\" fill=\"var(--muted)\" fill-opacity=\"0.3\" stroke=\"var(--muted)\" stroke-width=\"2\"/><text x=\"280\" y=\"190\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:30px;fill:var(--ink)\">x<tspan dy=\"-12\" style=\"font-family:KaTeX_Main,serif;font-style:normal;font-size:20px\">2</tspan></text><text x=\"280\" y=\"324\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:24px;fill:var(--ink)\">x</text><text x=\"420\" y=\"324\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:22px;fill:var(--red)\">dx</text><text x=\"470\" y=\"190\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:22px;fill:var(--red)\">x·dx</text><text x=\"280\" y=\"47\" text-anchor=\"middle\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:22px;fill:var(--red)\">x·dx</text><text x=\"456\" y=\"46\" style=\"font-family:KaTeX_Math,serif;font-style:italic;font-size:20px;fill:var(--muted)\">(dx)<tspan dy=\"-10\" style=\"font-family:KaTeX_Main,serif;font-style:normal;font-size:14px\">2</tspan></text></svg>"}],"t":[96120,111320]},{"show":["$\\Delta y=\\underbrace{2x\\,dx}_{dy}+(dx)^2$"],"say":"所以 得爾塔 y 等於 d y，加上 d x 平方。","board":[{"do":"write","line":"${{bx1:\\displaystyle \\Delta y=\\underbrace{2x\\,dx}_{dy}+(dx)^2}}$"},{"do":"box","term":"bx1","on":"加上"}],"t":[111320,117620]}]},{"title":"先猜猜看","beats":[{"show":["$y=x^3$，$x=2$，$dx=0.1$。$dy$ 和 $\\Delta y$ 哪個大？"],"say":"先猜猜看：x 立方，從 2 走 0.1，d y 和 得爾塔 y 哪個大？","t":[117620,130600]}],"predict":{"ask":"$y=x^3$，$x=2$，$dx=0.1$。$dy$ 和 $\\Delta y$ 哪個大？","options":[{"label":"$\\Delta y$ 比較大","correct":true},{"label":"$dy$ 比較大","why":"方向反了：曲線往上彎，切線在曲線下面，$dy$ 偏小"},{"label":"一樣大","why":"只有直線才會一樣大"}]}},{"title":"量測誤差會傳下去","beats":[{"show":["量 $x$ 有誤差 $dx$ → 用 $x$ 算出的 $y=f(x)$ 也有誤差","$\\text{誤差}\\ \\Delta y\\approx dy=f'(x)\\,dx$"],"say":"微分最常用來估計誤差。量 x 時有誤差 d x，算出來的 y 也會有誤差，大約是 d y，也就是 f prime x 乘 d x。","board":[{"do":"write","line":"量 $x$ 有誤差 $dx$ → 用 $x$ 算出的 $y=f(x)$ 也有誤差"},{"do":"write","line":"${{bx2:\\displaystyle \\text{誤差}\\ \\Delta y\\approx dy=f'(x)\\,dx}}$","on":"有誤#1"},{"do":"box","term":"bx2","on":"會有"},{"do":"write","line":"　$f'(x)$ 就是「放大倍率」：$x$ 差一點，$y$ 差 $f'(x)$ 倍那麼多","color":"violet","on":"pr"}],"t":[130600,144000]},{"show":["例：量得球的半徑 $r=10$ cm，誤差最多 $0.05$ cm。體積的最大誤差？"],"say":"例子：量得一顆球的半徑是 10 公分，誤差最多 0.05 公分。用它算體積，體積最多會差多少？","board":[{"do":"write","line":"例：量得球的半徑 $r=10$ cm，誤差最多 $0.05$ cm。體積的最大誤差？"}],"t":[144000,154660]},{"show":["$V=\\frac43\\pi r^3,\\qquad dV=4\\pi r^2\\,dr$"],"say":"體積是 3 分之 4 派 r 立方。微分：d V 等於 4 派 r 平方乘 d r。","board":[{"do":"write","line":"$\\displaystyle V=\\frac43\\pi r^3,\\qquad dV=4\\pi r^2\\,dr$"}],"t":[154660,165570]},{"show":["代 $r=10$、$|dr|\\le0.05$：","$|dV|\\le4\\pi(100)(0.05)=20\\pi\\approx62.8\\ \\text{cm}^3$"],"say":"代入 r 等於 10，d r 最多 0.05：4 派乘 100 乘 0.05，是 20 派，大約 62.8 立方公分。","board":[{"do":"write","line":"代 $r=10$、$|dr|\\le0.05$："},{"do":"write","line":"${{bx3:\\displaystyle |dV|\\le4\\pi(100)(0.05)=20\\pi\\approx62.8\\ \\text{cm}^3}}$","color":"red","on":"最多"},{"do":"box","term":"bx3","color":"red","on":"00"},{"do":"write","line":"　真正的 $\\Delta V$：半徑多 $0.05$ 時約 $63.1$，少 $0.05$ 時約 $-62.5$，都跟 $62.8$ 很接近","color":"violet","on":"大約"}],"t":[165570,177770]},{"show":["看起來很多？體積本身 $\\frac43\\pi(1000)\\approx4189$ cm³"],"say":"62.8 立方公分好像很多，但球本身的體積大約是 4189 立方公分。到底算大還是小，要跟本身比。這是第三節的主題。","board":[{"do":"write","line":"看起來很多？體積本身 $\\frac43\\pi(1000)\\approx4189$ cm³"}],"t":[177770,192810]}]},{"title":"試一題：正立方體","beats":[{"show":["正立方體邊長量得 $5$ cm，誤差 $0.02$ cm。用微分估計體積的誤差？"],"say":"換你試一題：正立方體邊長量得 5 公分，誤差 0.02 公分，體積誤差大約多少？","t":[192810,204900]}],"check":0},{"title":"試一題：正立方體","beats":[{"show":["$V=s^3$，$dV=3s^2\\,ds$：","$dV=3(5)^2(0.02)=1.5\\ \\text{cm}^3$"],"say":"解答：體積 s 立方，微分是 3 s 平方乘 d s。代入 5 和 0.02，得到 1.5 立方公分。","board":[{"do":"write","line":"$V=s^3$，$dV=3s^2\\,ds$："},{"do":"write","line":"${{bx4:\\displaystyle dV=3(5)^2(0.02)=1.5\\ \\text{cm}^3}}$","color":"red","on":"分是"},{"do":"box","term":"bx4","color":"red","on":"代入"},{"do":"write","line":"　真的 $\\Delta V=5.02^3-125=1.506008$，只差 $0.006$","color":"violet","on":"得到"}],"t":[204900,215500]},{"show":["放大倍率 $V'(5)=75$：邊長差 $1$ 份，體積差 $75$ 份"],"say":"這裡放大倍率是 75：邊長每差一點，體積就差 75 倍那麼多。","board":[{"do":"write","line":"放大倍率 $V'(5)=75$：邊長差 $1$ 份，體積差 $75$ 份"}],"t":[215500,223180]}]},{"title":"相對誤差","beats":[{"show":["相對誤差＝誤差 ÷ 本身：$\\dfrac{dy}{y}$；乘 $100\\%$ 是百分比誤差"],"say":"誤差大不大，要跟本身比。誤差除以本身，叫相對誤差；乘上百分之百，就是百分比誤差。","board":[{"do":"write","line":"相對誤差＝誤差 ÷ 本身：$\\dfrac{dy}{y}$；乘 $100\\%$ 是百分比誤差","color":"gold"}],"t":[223180,234580]},{"show":["球：","$\\frac{dV}{V}=\\frac{20\\pi}{\\frac43\\pi(1000)}=\\frac{60}{4000}=1.5\\%$"],"say":"剛剛的球：20 派，除以 3 分之 4 派乘 1000，等於 0.015，也就是百分之 1.5。","board":[{"do":"write","line":"球："},{"do":"write","line":"$\\displaystyle \\frac{dV}{V}=\\frac{20\\pi}{\\frac43\\pi(1000)}=\\frac{60}{4000}=1.5\\%$","on":"00#1"}],"t":[234580,244580]},{"show":["半徑的相對誤差：$\\dfrac{0.05}{10}=0.5\\%$"],"say":"而半徑的相對誤差，是 10 分之 0.05，只有百分之 0.5。","board":[{"do":"write","line":"半徑的相對誤差：$\\dfrac{0.05}{10}=0.5\\%$"}],"t":[244580,251380]},{"show":["體積的相對誤差剛好是 3 倍"],"say":"體積的相對誤差剛好是半徑的 3 倍。這不是巧合。","board":[{"do":"write","line":"體積的相對誤差剛好是 3 倍","color":"red"}],"t":[251380,259920]},{"show":["為什麼是 3 倍？ $y=x^n$：","$\\frac{dy}{y}=\\frac{nx^{n-1}\\,dx}{x^n}=n\\,\\frac{dx}{x}$"],"say":"看 x 的 n 次方。d y 是 n 乘 x 的 n 減 1 次方乘 d x；除以 x 的 n 次方，約完只剩 n 乘 x 分之 d x。","board":[{"do":"write","line":"為什麼是 3 倍？ $y=x^n$："},{"do":"write","line":"${{bx5:\\displaystyle \\frac{dy}{y}=\\frac{nx^{n-1}\\,dx}{x^n}=n\\,\\frac{dx}{x}}}$","on":"次方#2"},{"do":"box","term":"bx5","on":"次方#3"}],"t":[259920,274120]},{"show":["$y=x^n$ 的相對誤差＝$n$ 倍的 $x$ 的相對誤差"],"say":"所以 x 的 n 次方的相對誤差，是 x 的相對誤差的 n 倍。球的體積是半徑的三次方，所以放大 3 倍。","board":[{"do":"write","line":"$y=x^n$ 的相對誤差＝$n$ 倍的 $x$ 的相對誤差","color":"red"},{"do":"write","line":"　前面的常數（像 $\\frac43\\pi$）約掉了，不影響相對誤差","color":"violet","on":"球的"}],"t":[274120,285120]},{"show":["正立方體：$\\dfrac{dV}{V}=3\\cdot\\dfrac{0.02}5=1.2\\%$"],"say":"正立方體也一樣：邊長相對誤差是百分之 0.4，體積是 3 倍，百分之 1.2。1.5 除以 125，確實是 0.012。","board":[{"do":"write","line":"正立方體：$\\dfrac{dV}{V}=3\\cdot\\dfrac{0.02}5=1.2\\%$"}],"t":[285120,298980]}]},{"title":"反過來：要量多準","beats":[{"show":["用 $A=\\pi r^2$ 算圓面積，要 $\\left|\\dfrac{dA}{A}\\right|\\le1\\%$"],"say":"反過來問：用 派 r 平方算圓面積，要讓面積的相對誤差不超過百分之 1，半徑要量多準？","board":[{"do":"write","line":"用 $A=\\pi r^2$ 算圓面積，要 $\\left|\\dfrac{dA}{A}\\right|\\le1\\%$"}],"t":[298980,309280]},{"show":["$A$ 是 $r$ 的 2 次方：","$\\frac{dA}{A}=2\\,\\frac{dr}{r}$"],"say":"面積是半徑的 2 次方，所以面積的相對誤差，是半徑的 2 倍。","board":[{"do":"write","line":"$A$ 是 $r$ 的 2 次方："},{"do":"write","line":"$\\displaystyle \\frac{dA}{A}=2\\,\\frac{dr}{r}$","on":"積的"}],"t":[309280,315920]},{"show":["$2\\left|\\frac{dr}r\\right|\\le1\\%\\ \\Rightarrow\\ \\left|\\frac{dr}r\\right|\\le0.5\\%$"],"say":"2 倍的半徑相對誤差不超過百分之 1，所以半徑的相對誤差最多百分之 0.5。","board":[{"do":"write","line":"${{bx6:\\displaystyle 2\\left|\\frac{dr}r\\right|\\le1\\%\\ \\Rightarrow\\ \\left|\\frac{dr}r\\right|\\le0.5\\%}}$","color":"red"},{"do":"box","term":"bx6","color":"red","on":"過百"},{"do":"write","line":"　例：半徑約 $20$ cm，就要量到 $\\pm0.1$ cm 以內","color":"violet","on":"對誤#2"}],"t":[315920,324620]}],"check":1},{"title":"重點整理","beats":[{"show":["• $dy=f'(x)\\,dx$：沿切線的變化；$\\Delta y$：真正的變化","• $dx$ 小時 $\\Delta y\\approx dy$（差的是 $(dx)^2$ 那種更小的量）"],"say":"整理一下：d y 沿切線，得爾塔 y 是真正的變化，d x 小時兩個差不多。量測誤差乘上導數傳到結果；x 的 n 次方，相對誤差放大 n 倍。","board":[{"do":"write","line":"• $dy=f'(x)\\,dx$：沿切線的變化；$\\Delta y$：真正的變化"},{"do":"write","line":"• $dx$ 小時 $\\Delta y\\approx dy$（差的是 $(dx)^2$ 那種更小的量）","on":"爾塔"},{"do":"write","line":"• 量測誤差：$|\\Delta y|\\approx|f'(x)|\\,|dx|$，$f'$ 是放大倍率","on":"小時"},{"do":"write","line":"• 相對誤差 $\\frac{dy}y$；百分比誤差再乘 $100\\%$","on":"乘上"},{"do":"write","line":"• $y=x^n$：相對誤差放大 $n$ 倍；反過來要求就除以 $n$","on":"次方"}],"t":[342910,357510]},{"show":["下一課：Rolle 定理"],"say":"下一課，我們開始學微分的理論：羅爾定理。","board":[{"do":"write","line":"下一課：Rolle 定理"}],"t":[357510,364434]}]}],"checks":[{"ask":"正立方體邊長量得 $5$ cm，誤差 $0.02$ cm。用微分估計體積的誤差？","options":[{"label":"$1.5\\ \\text{cm}^3$","correct":true},{"label":"$0.5\\ \\text{cm}^3$","why":"漏了係數 $3$：$(s^3)'=3s^2$"},{"label":"$0.3\\ \\text{cm}^3$","why":"用了 $3s$；導數是 $3s^2$，要代 $s^2=25$"},{"label":"$0.02\\ \\text{cm}^3$","why":"那是邊長的誤差，還沒乘上放大倍率 $V'(s)$"}]},{"ask":"正立方體的體積要準到 $\\pm3\\%$，邊長的相對誤差最多可以是？","options":[{"label":"$1\\%$","correct":true},{"label":"$9\\%$","why":"方向反了：體積的誤差是邊長的 $3$ 倍，所以邊長要更準"},{"label":"$3\\%$","why":"忘了放大 $3$ 倍"},{"label":"$\\sqrt[3]{3}\\%\\approx1.44\\%$","why":"相對誤差是乘以 $n$，不是開 $n$ 次方"}]}],"practice":[{"id":"lec-05-q4b","core":true},{"id":"dd-lin-005","core":true},{"id":"db-lin-006","core":true},{"id":"db-lin-007","core":true},{"id":"cg-3d-006","core":true},{"id":"cg-3d-003","core":true},{"id":"cg-3d-007"},{"id":"cg-3d-004"},{"id":"cg-3d-005"}]}});
